const payload = $('Execute Workflow Trigger').item.json || {};
const msg = payload.message || payload.body?.message || payload;
const rawText = String(msg?.text || payload.text || '' || payload.query || '').trim();
const chatId = msg?.chat?.id || payload.chatId || '';
const calendarId = payload.calendarId || 'kuminhuynhdoan@gmail.com';

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0111/g, 'd')
    .replace(/\u0110/g, 'D')
    .trim();
}

const text = normalize(rawText);
let action = 'help';

if (/\b(calendar help|lich help|huong dan calendar|huong dan lich|google calendar help|help calendar)\b/.test(text)) {
  action = 'help';
} else if (/\b(xoa lich|huy lich|delete event|cancel event)\b/.test(text)) {
  action = 'delete_event';
} else if (/\b(kiem tra lich ranh|check lich ranh|co ranh|freebusy|availability|ranh luc)\b/.test(text)) {
  action = 'check_availability';
} else if (/\b(tao lich|dat lich|them lich|tao su kien|dat su kien|book lich|create event)\b/.test(text)) {
  action = 'create_event';
} else if (/\b(lich ngay mai|ngay mai toi co gi|mai toi co gi|list tomorrow|tomorrow schedule)\b/.test(text)) {
  action = 'list_tomorrow';
} else if (/\b(lich hom nay|hom nay toi co gi|xem lich hom nay|today schedule|list today)\b/.test(text)) {
  action = 'list_today';
} else if (/\b(lich|su kien|meeting|hop|calendar|tuan sau|cuoi tuan nay|thu [2-7]|chu nhat)\b/.test(text)) {
  action = 'find_event';
}

return [{ json: { payload, message: msg, chatId, rawText, text, action, calendarId } }];

const workflowMap = {
  create_event: 'Sub-workflow: Google Calendar - Create Event',
  list_today: 'Sub-workflow: Google Calendar - List Today',
  list_tomorrow: 'Sub-workflow: Google Calendar - List Tomorrow',
  find_event: 'Sub-workflow: Google Calendar - Find Event',
  delete_event: 'Sub-workflow: Google Calendar - Delete Event',
  check_availability: 'Sub-workflow: Google Calendar - Check Availability',
  help: 'Sub-workflow: Google Calendar - Help'
};

const workflowName = workflowMap[$json.action] || workflowMap.help;
return [{ json: { ...$json, workflowName } }];

const workflows = $input.item.json.data || [];
const source = $('Chon Workflow Calendar').item.json;
const found = workflows.find((workflow) => workflow.name === source.workflowName);

if (!found) {
  return [{
    json: {
      ...source,
      hasWorkflow: false,
      response: `Khong tim thay workflow con: ${source.workflowName}`
    }
  }];
}

return [{
  json: {
    ...source,
    hasWorkflow: true,
    workflowId: found.id
  }
}];

const source = $json || {};
const fallback = source.response || '⚠️ Mia chưa xử lý được yêu cầu này lúc này.';
return [{ json: { chatId: source.chatId || '', text: fallback } }];

const source = $input.item.json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2 ($1)')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const rawText = String(
  source.text ||
  source.responseText ||
  source.output ||
  source.response ||
  ''
).trim();

const plainText = String(source.plainText || htmlToPlainText(rawText)).trim();

return [{
  json: {
    ...source,
    text: plainText || rawText
  }
}];
